contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 a,
        uint64 b,
        uint256 d,
        bytes32 e,
        uint64 f,
        bytes32 g,
        uint256 h,
        uint256 i
    ) public payable {
        require(address(this) != address(0), "unreachable");

        // Read the before-values through public getters.
        uint64 beforeNumber = c.number();
        uint64 beforeTimestamp = c.timestamp();
        uint256 beforeBasefee = c.basefee();
        bytes32 beforeHash = c.hash();
        uint64 beforeSequenceNumber = c.sequenceNumber();
        bytes32 beforeBatcherHash = c.batcherHash();
        uint256 beforeL1FeeOverhead = c.l1FeeOverhead();
        uint256 beforeL1FeeScalar = c.l1FeeScalar();

        // The test contract is not the depositor account, so this call must revert.
        bool reverted;
        try c.setL1BlockValues(a, b, d, e, f, g, h, i) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the call reverts and no observable state changes.
        assert(
            reverted &&
            c.number() == beforeNumber &&
            c.timestamp() == beforeTimestamp &&
            c.basefee() == beforeBasefee &&
            c.hash() == beforeHash &&
            c.sequenceNumber() == beforeSequenceNumber &&
            c.batcherHash() == beforeBatcherHash &&
            c.l1FeeOverhead() == beforeL1FeeOverhead &&
            c.l1FeeScalar() == beforeL1FeeScalar
        );
    }
}

